defmodule StatusServer do
  use GenServer
  @moduledoc "Public v1 protocol: GenServer.call(pid, :snapshot) returns {:ready, count}."
  def start_link(count), do: GenServer.start_link(__MODULE__, count)
  def init(count), do: {:ok, count}
  def handle_call(:snapshot, _from, count), do: {:reply, {:ready, count}, count}
end

